sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var mssTreasuryUtils = new x_hsb11_mss_tsd.MSS_Treasury_Utils();
    try {
        var accessDetails = mssTreasuryUtils.canAssignToMe(current.state, current.getDisplayValue('assignment_group'));
        g_scratchpad.isManager = accessDetails ? accessDetails.isManager : false;
        g_scratchpad.flag = accessDetails ? accessDetails.flag : false;
        // MSSTRESURY-299/296/298/314/452 - Preventing Same User performing Maker and Checker Task
        var assignToInfo = mssTreasuryUtils.taskAlreadyAssignTo(current);
        g_scratchpad.taskAlreadyAssignTo = assignToInfo;
    } catch (errorInfo) {
		var errorMessage = "[iQube - Treasury]: Business Rule - Display Current Assigned User - Inst Error: " + errorInfo.message;
		new x_hsb11_mss_tsd.MSS_Treasury_XMatter_ITID_WidgetFailureHandler().createITIDEvent("MINOR", errorMessage, 'MSS-OT-IQUBE-SERVICENOW-TREASURY');
		gs.error(errorMessage);
    }

})(current, previous);
